-- ============================================================================
-- B5 FOLLOW-ON W1, D4 PART C: the open-book label on the waterflood capstone
-- brief.
--
-- WHY. A lesson or a panel's opening view prints the answers these capstones
-- grade (docs/graded-field-audit/README.md finding 3; FOLLOW-ON-PROGRAMME.md
-- section 3). Until W5 re-cases or strips them, the brief says so. The label is
-- the brief's first sentence; the rest of the prompt is unchanged. The same
-- note heads the tier's capstone lesson (NextGen zip).
--
-- beginner: every graded figure(s) printed; section 3 pick A (re-case)
-- intermediate: every graded figure(s) printed; section 3 pick A (re-case)
-- advanced: every graded figure(s) printed; section 3 pick A (re-case)
--
-- THE LABEL:
--   Open book: the figures this capstone grades can be read in this tier's
--   lessons or on a panel as it opens, so for now it checks that you can find,
--   read and report each one correctly. A later update moves it to a case of its
--   own.
--
-- WHAT DOES NOT MOVE. `fields` (every key, label, unit, expected and
-- tolerance), title, dataset, status and the row. The guard requires `fields`
-- to equal its post-20261024a value exactly, before and after, so no answer
-- grades differently and no attempt guard is needed.
--
-- GUARDS. Each prompt must hold its post-20261024a text (md5, rewritten) or
-- its labelled text (left alone). Anything else raises and the file rolls
-- back. Runs after 20261024a_w1_*. Generated by
-- docs/graded-field-audit/w1_capstones.py. SAFE TO RE-RUN.
-- ============================================================================

do $$
declare
  v_n        integer;
  v_count    integer;
  v_written  integer := 0;
  v_ids      jsonb;
  v_extra    jsonb;
  v_idtxt    text;
  v_allow    jsonb := '{}'::jsonb;  -- D5 allowlist: 'course/tier' -> attempt ids signed off
  v_s0       text;
  v_s1       text;
  v_s2       text;
begin
  -- waterflood / beginner
  select count(*) into v_n from public.academy_capstones where app_slug = 'waterflood' and tier = 'beginner' and active;
  if v_n <> 1 then raise exception 'w1 open-book waterflood refused: waterflood/beginner has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = 'fdca01fba51a8cb58a3f1b1a4bbb306d' and fields = '[{"key": "field_cum_vrr", "tol": 0.0005, "unit": "-", "label": "Field cumulative VRR", "expected": 1.034899536109}, {"key": "produced_voidage_rb", "tol": 50, "unit": "rb", "label": "Total produced voidage", "expected": 221736.43680913927}, {"key": "injected_voidage_rb", "tol": 50, "unit": "rb", "label": "Total injected voidage", "expected": 229474.93559224083}, {"key": "fillup_month_index", "tol": 0, "unit": "index", "label": "Fill-up period index (zero-based)", "expected": 11}, {"key": "months_under_target_band", "tol": 0, "unit": "count", "label": "Periods under the 1.00 to 1.20 band", "expected": 4}, {"key": "jan_produced_voidage_rb", "tol": 1, "unit": "rb", "label": "January 2023 produced voidage", "expected": 5747.317402456214}]'::jsonb then 'old'
              when md5(prompt) = '74f60dfa30099fe45a3022f85052b7bf' and fields = '[{"key": "field_cum_vrr", "tol": 0.0005, "unit": "-", "label": "Field cumulative VRR", "expected": 1.034899536109}, {"key": "produced_voidage_rb", "tol": 50, "unit": "rb", "label": "Total produced voidage", "expected": 221736.43680913927}, {"key": "injected_voidage_rb", "tol": 50, "unit": "rb", "label": "Total injected voidage", "expected": 229474.93559224083}, {"key": "fillup_month_index", "tol": 0, "unit": "index", "label": "Fill-up period index (zero-based)", "expected": 11}, {"key": "months_under_target_band", "tol": 0, "unit": "count", "label": "Periods under the 1.00 to 1.20 band", "expected": 4}, {"key": "jan_produced_voidage_rb", "tol": 1, "unit": "rb", "label": "January 2023 produced voidage", "expected": 5747.317402456214}]'::jsonb then 'new'
              else 'other' end
    into v_s0 from public.academy_capstones where app_slug = 'waterflood' and tier = 'beginner' and active;
  if v_s0 = 'other' then
    raise exception 'w1 open-book waterflood refused: waterflood/beginner matches neither its published form (prompt md5 fdca01fba51a8cb58a3f1b1a4bbb306d) nor its W1 form (prompt md5 74f60dfa30099fe45a3022f85052b7bf), with the fields this file was generated against';
  end if;

  -- waterflood / intermediate
  select count(*) into v_n from public.academy_capstones where app_slug = 'waterflood' and tier = 'intermediate' and active;
  if v_n <> 1 then raise exception 'w1 open-book waterflood refused: waterflood/intermediate has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = 'd89caf9ab31ed7a175cb909ccf246b12' and fields = '[{"key": "out_of_zone_bbl", "tol": 20, "unit": "bbl", "label": "Out-of-zone injection", "expected": 26997.051246145966}, {"key": "north_cum_vrr", "tol": 0.0005, "unit": "-", "label": "North element cumulative VRR", "expected": 1.2024353717815623}, {"key": "south_cum_vrr", "tol": 0.0005, "unit": "-", "label": "South element cumulative VRR", "expected": 0.6097477559533482}, {"key": "south_recommended_wi", "tol": 2, "unit": "bbl", "label": "South recommended injection at target 1.0", "expected": 2683.051749612857}, {"key": "hall_ratio_e4", "tol": 0.0005, "unit": "-", "label": "Ekene-4 Hall slope ratio above the reference", "expected": 1.4285714285714286}, {"key": "chan_slope_e6", "tol": 0.005, "unit": "-", "label": "Ekene-6 Chan late-time slope", "expected": 2.348281726147951}]'::jsonb then 'old'
              when md5(prompt) = '86d604bff13f405a61ea14ab3aba8f67' and fields = '[{"key": "out_of_zone_bbl", "tol": 20, "unit": "bbl", "label": "Out-of-zone injection", "expected": 26997.051246145966}, {"key": "north_cum_vrr", "tol": 0.0005, "unit": "-", "label": "North element cumulative VRR", "expected": 1.2024353717815623}, {"key": "south_cum_vrr", "tol": 0.0005, "unit": "-", "label": "South element cumulative VRR", "expected": 0.6097477559533482}, {"key": "south_recommended_wi", "tol": 2, "unit": "bbl", "label": "South recommended injection at target 1.0", "expected": 2683.051749612857}, {"key": "hall_ratio_e4", "tol": 0.0005, "unit": "-", "label": "Ekene-4 Hall slope ratio above the reference", "expected": 1.4285714285714286}, {"key": "chan_slope_e6", "tol": 0.005, "unit": "-", "label": "Ekene-6 Chan late-time slope", "expected": 2.348281726147951}]'::jsonb then 'new'
              else 'other' end
    into v_s1 from public.academy_capstones where app_slug = 'waterflood' and tier = 'intermediate' and active;
  if v_s1 = 'other' then
    raise exception 'w1 open-book waterflood refused: waterflood/intermediate matches neither its published form (prompt md5 d89caf9ab31ed7a175cb909ccf246b12) nor its W1 form (prompt md5 86d604bff13f405a61ea14ab3aba8f67), with the fields this file was generated against';
  end if;

  -- waterflood / advanced
  select count(*) into v_n from public.academy_capstones where app_slug = 'waterflood' and tier = 'advanced' and active;
  if v_n <> 1 then raise exception 'w1 open-book waterflood refused: waterflood/advanced has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = 'e530e5e3b42f0223816bba635d0d82dd' and fields = '[{"key": "dykstra_parsons_v", "tol": 0.001, "unit": "-", "label": "Dykstra-Parsons permeability variation V", "expected": 0.5}, {"key": "dp_coverage_first_bt", "tol": 0.0005, "unit": "fraction", "label": "Coverage at the first breakthrough", "expected": 0.5146907350993352}, {"key": "stiles_wc_first_bt", "tol": 0.0005, "unit": "fraction", "label": "Stiles surface water cut at first BT", "expected": 0.5843728303284756}, {"key": "eabt_at_design_m", "tol": 0.0005, "unit": "fraction", "label": "Areal sweep at breakthrough at M = 1.2", "expected": 0.6573574366303985}, {"key": "design_breakthrough_days", "tol": 2, "unit": "days", "label": "Design-case breakthrough time", "expected": 639.1875}, {"key": "implied_swept_fraction", "tol": 0.0002, "unit": "fraction", "label": "Implied contacted fraction of the element", "expected": 0.014697005138728762}]'::jsonb then 'old'
              when md5(prompt) = '61a1e3b3679d2b2c40d89bc94fcfa1cd' and fields = '[{"key": "dykstra_parsons_v", "tol": 0.001, "unit": "-", "label": "Dykstra-Parsons permeability variation V", "expected": 0.5}, {"key": "dp_coverage_first_bt", "tol": 0.0005, "unit": "fraction", "label": "Coverage at the first breakthrough", "expected": 0.5146907350993352}, {"key": "stiles_wc_first_bt", "tol": 0.0005, "unit": "fraction", "label": "Stiles surface water cut at first BT", "expected": 0.5843728303284756}, {"key": "eabt_at_design_m", "tol": 0.0005, "unit": "fraction", "label": "Areal sweep at breakthrough at M = 1.2", "expected": 0.6573574366303985}, {"key": "design_breakthrough_days", "tol": 2, "unit": "days", "label": "Design-case breakthrough time", "expected": 639.1875}, {"key": "implied_swept_fraction", "tol": 0.0002, "unit": "fraction", "label": "Implied contacted fraction of the element", "expected": 0.014697005138728762}]'::jsonb then 'new'
              else 'other' end
    into v_s2 from public.academy_capstones where app_slug = 'waterflood' and tier = 'advanced' and active;
  if v_s2 = 'other' then
    raise exception 'w1 open-book waterflood refused: waterflood/advanced matches neither its published form (prompt md5 e530e5e3b42f0223816bba635d0d82dd) nor its W1 form (prompt md5 61a1e3b3679d2b2c40d89bc94fcfa1cd), with the fields this file was generated against';
  end if;

  -- nothing to write: every row is already in its W1 form
  if v_s0 = 'new' and v_s1 = 'new' and v_s2 = 'new' then
    raise notice 'w1 open-book waterflood: 0 of 3 row(s) written, all already applied';
    return;
  end if;

  -- the round-off batch (20261023*) must be applied first: its rows are this file's base
  if exists (select 1 from public.academy_capstones where app_slug = 'cementing' and tier = 'advanced' and active and md5(prompt) <> '7e7412057740dcb01936e298c2026745')
     or exists (select 1 from public.academy_capstones where app_slug = 'casingtubing' and tier = 'advanced' and active and md5(prompt) <> 'f7e6749b9be66d4dbc7e692745d656d7')
     or exists (select 1 from public.academy_capstones where app_slug = 'gaswell' and tier = 'advanced' and active and md5(prompt) <> '07f6076362de4a93714236cc10af4012')
     or exists (select 1 from public.academy_capstones where app_slug = 'wellcontrol' and tier = 'beginner' and active and md5(dataset) <> '228b1d1a73f0474291f6142741bab7b2')
     or exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                 where c.app_slug = 'fiscal' and c.tier = 'intermediate' and c.active and f->>'key' = 'psc_npv_musd'
                   and (f->>'tol')::float8 <> 0.05) then
    raise exception 'w1 open-book waterflood refused: the round-off batch (20261023*) is not applied on this database; apply it first (/root/roundoff-apply/apply.sh apply --prod)';
  end if;

  if v_s0 = 'old' then
    update public.academy_capstones
       set prompt = 'Open book: the figures this capstone grades can be read in this tier''s lessons or on a panel as it opens, so for now it checks that you can find, read and report each one correctly. A later update moves it to a case of its own. Work the Ekene waterflood ledger over its 36 monthly periods, 2023-01 through 2025-12, on the frozen factor set Bo 1.21584, Bw 1.02, Bg 0 and Rs 400 scf/stb. Report the cumulative voidage replacement ratio as the ratio of the summed voidages, the total produced and injected voidage in reservoir barrels, the zero-based index of the first period at which the CUMULATIVE ratio reaches or exceeds 1.0, the number of periods whose INSTANTANEOUS ratio falls below an operator target band of 1.00 to 1.20, and the produced voidage of January 2023 alone. Only free produced gas adds voidage: subtract the solution gas Rs*Np/1000 from the metered gas before converting.',
           fields = '[{"key": "field_cum_vrr", "tol": 0.0005, "unit": "-", "label": "Field cumulative VRR", "expected": 1.034899536109}, {"key": "produced_voidage_rb", "tol": 50, "unit": "rb", "label": "Total produced voidage", "expected": 221736.43680913927}, {"key": "injected_voidage_rb", "tol": 50, "unit": "rb", "label": "Total injected voidage", "expected": 229474.93559224083}, {"key": "fillup_month_index", "tol": 0, "unit": "index", "label": "Fill-up period index (zero-based)", "expected": 11}, {"key": "months_under_target_band", "tol": 0, "unit": "count", "label": "Periods under the 1.00 to 1.20 band", "expected": 4}, {"key": "jan_produced_voidage_rb", "tol": 1, "unit": "rb", "label": "January 2023 produced voidage", "expected": 5747.317402456214}]'::jsonb
     where app_slug = 'waterflood' and tier = 'beginner' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 open-book waterflood refused: waterflood/beginner updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '74f60dfa30099fe45a3022f85052b7bf' and fields = '[{"key": "field_cum_vrr", "tol": 0.0005, "unit": "-", "label": "Field cumulative VRR", "expected": 1.034899536109}, {"key": "produced_voidage_rb", "tol": 50, "unit": "rb", "label": "Total produced voidage", "expected": 221736.43680913927}, {"key": "injected_voidage_rb", "tol": 50, "unit": "rb", "label": "Total injected voidage", "expected": 229474.93559224083}, {"key": "fillup_month_index", "tol": 0, "unit": "index", "label": "Fill-up period index (zero-based)", "expected": 11}, {"key": "months_under_target_band", "tol": 0, "unit": "count", "label": "Periods under the 1.00 to 1.20 band", "expected": 4}, {"key": "jan_produced_voidage_rb", "tol": 1, "unit": "rb", "label": "January 2023 produced voidage", "expected": 5747.317402456214}]'::jsonb) from public.academy_capstones where app_slug = 'waterflood' and tier = 'beginner' and active) is not true then
    raise exception 'w1 open-book waterflood refused: waterflood/beginner does not read back as its W1 form';
  end if;

  if v_s1 = 'old' then
    update public.academy_capstones
       set prompt = 'Open book: the figures this capstone grades can be read in this tier''s lessons or on a panel as it opens, so for now it checks that you can find, read and report each one correctly. A later update moves it to a case of its own. Take the Ekene flood apart by geometry. The allocation matrix routes Ekene-2 to Ekene-6 0.45, Ekene-1 0.30 and Ekene-3 0.15, and Ekene-4 to Ekene-3 0.40, Ekene-6 0.35 and Ekene-5 0.10. The two elements are North, holding Ekene-1 and Ekene-6, and South, holding Ekene-3 and Ekene-5. Report the injected volume that lands on no producer, each element''s cumulative VRR on the frozen factor set, and the injection recommended for the South element at a target VRR of 1.0 over a three-period trailing window, scaled from the ALLOCATED injection into that element. Then two diagnostics on the raw well data: the Hall plot slope ratio for Ekene-4 built on pressure ABOVE the 2050 psia injection reference, and the late-time log-log slope of the water oil ratio derivative for Ekene-6.',
           fields = '[{"key": "out_of_zone_bbl", "tol": 20, "unit": "bbl", "label": "Out-of-zone injection", "expected": 26997.051246145966}, {"key": "north_cum_vrr", "tol": 0.0005, "unit": "-", "label": "North element cumulative VRR", "expected": 1.2024353717815623}, {"key": "south_cum_vrr", "tol": 0.0005, "unit": "-", "label": "South element cumulative VRR", "expected": 0.6097477559533482}, {"key": "south_recommended_wi", "tol": 2, "unit": "bbl", "label": "South recommended injection at target 1.0", "expected": 2683.051749612857}, {"key": "hall_ratio_e4", "tol": 0.0005, "unit": "-", "label": "Ekene-4 Hall slope ratio above the reference", "expected": 1.4285714285714286}, {"key": "chan_slope_e6", "tol": 0.005, "unit": "-", "label": "Ekene-6 Chan late-time slope", "expected": 2.348281726147951}]'::jsonb
     where app_slug = 'waterflood' and tier = 'intermediate' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 open-book waterflood refused: waterflood/intermediate updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '86d604bff13f405a61ea14ab3aba8f67' and fields = '[{"key": "out_of_zone_bbl", "tol": 20, "unit": "bbl", "label": "Out-of-zone injection", "expected": 26997.051246145966}, {"key": "north_cum_vrr", "tol": 0.0005, "unit": "-", "label": "North element cumulative VRR", "expected": 1.2024353717815623}, {"key": "south_cum_vrr", "tol": 0.0005, "unit": "-", "label": "South element cumulative VRR", "expected": 0.6097477559533482}, {"key": "south_recommended_wi", "tol": 2, "unit": "bbl", "label": "South recommended injection at target 1.0", "expected": 2683.051749612857}, {"key": "hall_ratio_e4", "tol": 0.0005, "unit": "-", "label": "Ekene-4 Hall slope ratio above the reference", "expected": 1.4285714285714286}, {"key": "chan_slope_e6", "tol": 0.005, "unit": "-", "label": "Ekene-6 Chan late-time slope", "expected": 2.348281726147951}]'::jsonb) from public.academy_capstones where app_slug = 'waterflood' and tier = 'intermediate' and active) is not true then
    raise exception 'w1 open-book waterflood refused: waterflood/intermediate does not read back as its W1 form';
  end if;

  if v_s2 = 'old' then
    update public.academy_capstones
       set prompt = 'Open book: the figures this capstone grades can be read in this tier''s lessons or on a panel as it opens, so for now it checks that you can find, read and report each one correctly. A later update moves it to a case of its own. Design and then check the Ekene flood. The sand is five non-communicating layers, given in DEPTH order with thicknesses 18, 22, 16, 14 and 14 ft and permeabilities 173.81198701129736, 607.7507038307907, 250, 102.8382190362731 and 359.5839451276606 md; the endpoint mobility ratio is 1.2 and the frozen factors are Bo 1.21584 and Bw 1.02. Report the Dykstra-Parsons permeability variation V, the vertical coverage at the FIRST layer breakthrough at that mobility ratio, the Stiles surface water cut at the same stage using the capacity ratio A = M*Bo/Bw, and the Craig five-spot areal sweep at breakthrough evaluated at the mobility ratio. Then forecast the five-spot element of 208.8040473397547 acres and 34.585155812896204 ft net at porosity 0.2, injecting 2000 rb/d with the vertical sweep taken from your own coverage answer and a water oil ratio limit of 25, and report the breakthrough time as the engine reports it, on whole monthly steps of 30.4375 days. Finally, invert the pattern breakthrough condition on the 35106.29313483455 bbl the allocation routed to Ekene-6 before its 2024-03-01 breakthrough, and report the contacted pore volume as a fraction of the WHOLE element, 11205422.76570545 rb, computed without the vertical sweep multiplier.',
           fields = '[{"key": "dykstra_parsons_v", "tol": 0.001, "unit": "-", "label": "Dykstra-Parsons permeability variation V", "expected": 0.5}, {"key": "dp_coverage_first_bt", "tol": 0.0005, "unit": "fraction", "label": "Coverage at the first breakthrough", "expected": 0.5146907350993352}, {"key": "stiles_wc_first_bt", "tol": 0.0005, "unit": "fraction", "label": "Stiles surface water cut at first BT", "expected": 0.5843728303284756}, {"key": "eabt_at_design_m", "tol": 0.0005, "unit": "fraction", "label": "Areal sweep at breakthrough at M = 1.2", "expected": 0.6573574366303985}, {"key": "design_breakthrough_days", "tol": 2, "unit": "days", "label": "Design-case breakthrough time", "expected": 639.1875}, {"key": "implied_swept_fraction", "tol": 0.0002, "unit": "fraction", "label": "Implied contacted fraction of the element", "expected": 0.014697005138728762}]'::jsonb
     where app_slug = 'waterflood' and tier = 'advanced' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 open-book waterflood refused: waterflood/advanced updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '61a1e3b3679d2b2c40d89bc94fcfa1cd' and fields = '[{"key": "dykstra_parsons_v", "tol": 0.001, "unit": "-", "label": "Dykstra-Parsons permeability variation V", "expected": 0.5}, {"key": "dp_coverage_first_bt", "tol": 0.0005, "unit": "fraction", "label": "Coverage at the first breakthrough", "expected": 0.5146907350993352}, {"key": "stiles_wc_first_bt", "tol": 0.0005, "unit": "fraction", "label": "Stiles surface water cut at first BT", "expected": 0.5843728303284756}, {"key": "eabt_at_design_m", "tol": 0.0005, "unit": "fraction", "label": "Areal sweep at breakthrough at M = 1.2", "expected": 0.6573574366303985}, {"key": "design_breakthrough_days", "tol": 2, "unit": "days", "label": "Design-case breakthrough time", "expected": 639.1875}, {"key": "implied_swept_fraction", "tol": 0.0002, "unit": "fraction", "label": "Implied contacted fraction of the element", "expected": 0.014697005138728762}]'::jsonb) from public.academy_capstones where app_slug = 'waterflood' and tier = 'advanced' and active) is not true then
    raise exception 'w1 open-book waterflood refused: waterflood/advanced does not read back as its W1 form';
  end if;

  raise notice 'w1 open-book waterflood: % of 3 row(s) written, % already applied', v_written, 3 - v_written;
end $$;
